package main

import (
	"encoding/json"
	"fmt"
	"log"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// Internal message types for cluster communication
type InternalMessage struct {
	Src  string `json:"src"`
	Dest string `json:"dest"`
	Body map[string]bool `json:"body"` // key: value, value: whether already sent (for deduplication)
}

// BroadcastCluster implements a broadcast cluster where values are shared across nodes
type BroadcastCluster struct {
	mu      sync.RWMutex
	myID    string
	nodeIDs []string
	values  map[string]struct{}
	watchers map[string][]chan internalBroadcastMessage // which nodes should get this value (value -> list of channels)
}

// Handle processes incoming messages
func (c *BroadcastCluster) Handle() {
	for {
		switch m := <-maelstrom.Reply(); m.Type {
		case "init":
			c.mu.Lock()
			c.myID = m.ID
			c.nodeIDs = m.NodeIDs
			if c.nodeIDs == nil {
				c.nodeIDs = []string{c.myID}
			}
			c.values = make(map[string]struct{})
			c.watchers = make(map[string][]chan internalBroadcastMessage)
			c.mu.Unlock()

			// Send topology_ok immediately to acknowledge receipt
			c.RPC("topology_ok", m.Body)

		case "broadcast":
			val := int(m.Message.(int)) // convert msg_id to int for value
			c.mu.Lock()
			c.values[val] = struct{}{}
			c.mu.Unlock()
			c.maelstrom.Reply("broadcast_ok", nil, 0) // reply to broadcast request

		case "read":
			vals := make(map[int]struct{})
			c.mu.RLock()
			for k := range c.values {
				vals[k] = struct{}{}
			}
			c.mu.RUnlock()

			// Send read_ok with the values as messages
			respMessages := make([]int, 0, len(vals))
			for v := range vals {
				respMessages = append(respMessages, v)
			}
			// Sort for consistent ordering
			sortInts(respMessages)
			c.maelstrom.Reply("read_ok", respMessages, 0)

		case "topology":
			c.RPC("topology_ok", m.Body)
		}
	}
}

// Start runs the node
func (c *BroadcastCluster) Run() {
	log.Println("Running broadcast cluster")
}

func sortInts(arr []int) {
	for i := 0; i < len(arr)-1; i++ {
		for j := i + 1; j < len(arr); j++ {
			if arr[i] > arr[j] {
				arr[i], arr[j] = arr[j], arr[i]
			}
		}
	}
}

// internalBroadcastMessage for handling broadcasts from other nodes
type internalBroadcastMessage struct {
	Value int `json:"value"`
	Src   string `json:"src"`
	Dest  string `json:"dest"`
}

func (c *BroadcastCluster) sendInternalMessage(src, dest string, val int) bool {
	msg := InternalMessage{Src: src, Dest: dest, Body: map[string]bool{"value": true}}
	// Encode JSON and send as RPC to the other node
	jsonBody, err := json.Marshal(msg)
	if err != nil {
		log.Printf("Error encoding internal message: %v", err)
		return false
	}
	c.maelstrom.Send(dest, jsonBody)
	return true
}

func (c *BroadcastCluster) broadcastValue(value int, src string) bool {
	c.mu.Lock()
	valuesToDistribute := []int{value} // initially just this value
	alreadySent := make(map[string]bool)

	for _, v := range c.values {
		if !alreadySent[v] && v == value {
			// We already sent this to all watchers
		} else if !alreadySent[v] {
			alreadySent[v] = true
		}
	}

	// Send to all other nodes (broadcast style)
	for _, dest := range c.nodeIDs {
		if src != dest && c.sendInternalMessage(src, dest, value) {
			alreadySent[dest] = true
		}
	}

	c.mu.Unlock()

	return true
}

func (c *BroadcastCluster) replyToInternalMsg(msg internalBroadcastMessage, value int) {
	// Forward to all other nodes
	for _, nodeID := range c.nodeIDs {
		if msg.Src != nodeID {
			c.sendInternalMessage(nodeID, msg.Dest, value)
		}
	}
}

func (c *BroadcastCluster) processInternalMessage(msg internalBroadcastMessage) {
	value := msg.Value
	// Broadcast to all other nodes in the cluster
	for _, dest := range c.nodeIDs {
		if msg.Src != dest {
			c.sendInternalMessage(msg.Src, dest, value)
		}
	}
}

func (c *BroadcastCluster) handleRPC() {
	// Handle RPC from other nodes
	for {
		msg := <-maelstrom.Reply()
		if msg.Type == "broadcast" {
			val := int(msg.Message.(int))

			// Store locally
			c.mu.Lock()
			c.values[val] = struct{}{}
			c.mu.Unlock()

			// Forward to all other nodes
			for _, dest := range c.nodeIDs {
				if msg.Src != dest {
					c.sendInternalMessage(msg.Src, dest, val)
				}
			}

			// Reply back with broadcast_ok
			c.RPC("broadcast_ok", nil, 0)
		}
	}
}

func (c *BroadcastCluster) handleSend() {
	// Handle Send from other nodes
	for {
		msg := <-maelstrom.Reply()

		var internalMsg InternalMessage
		if err := json.Unmarshal(msg.Body, &internalMsg); err != nil {
			log.Printf("Error unmarshaling internal message: %v", err)
			continue
		}

		value := internalMsg.Body["value"].(int)
		c.mu.Lock()
		c.values[value] = struct{}{}
		c.mu.Unlock()
	}
}

func (c *BroadcastCluster) mainLoop() {
	var wg sync.WaitGroup

	// Start RPC handler
	wg.Add(1)
	go func() {
		defer wg.Done()
		c.handleRPC()
	}()

	// Handle broadcast and read directly in the Reply loop
	for {
		msg := <-maelstrom.Reply()

		switch msg.Type {
		case "broadcast":
			val := int(msg.Message.(int))
			// Store locally and forward to all other nodes
			c.mu.Lock()
			c.values[val] = struct{}{}
			c.mu.Unlock()

			// Forward to all other nodes
			for _, dest := range c.nodeIDs {
				if msg.Src != dest {
					c.sendInternalMessage(msg.Src, dest, val)
				}
			}
			c.maelstrom.Reply("broadcast_ok", nil, 0)

		case "read":
			vals := make(map[int]struct{})
			c.mu.RLock()
			for k := range c.values {
				vals[k] = struct{}{}
			}
			c.mu.RUnlock()

			respMessages := make([]int, 0, len(vals))
			for v := range vals {
				respMessages = append(respMessages, v)
			}
			sortInts(respMessages)
			c.maelstrom.Reply("read_ok", respMessages, 0)

		case "topology":
			c.RPC("topology_ok", msg.Body)

		case "broadcast_ok":
			// Just reply with nothing (acknowledgement)
			c.RPC("broadcast_ack", nil, 0)

		case "read_ok":
			// Just reply with nothing (acknowledgement)
			c.RPC("read_ack", nil, 0)

		case "internal_message":
			var internalMsg InternalMessage
			if err := json.Unmarshal(msg.Body, &internalMsg); err != nil {
				log.Printf("Error unmarshaling internal message: %v", err)
				continue
			}

			value := internalMsg.Body["value"].(int)

			c.mu.Lock()
			c.values[value] = struct{}{}
			c.mu.Unlock()

			// Forward to all other nodes
			for _, dest := range c.nodeIDs {
				if msg.Src != dest {
					c.sendInternalMessage(msg.Src, dest, value)
				}
			}

			// Reply back with acknowledgment
			c.RPC("internal_msg_ack", nil, 0)

		default:
			log.Printf("Unhandled message type: %s", msg.Type)
		}
	}
}

func (c *BroadcastCluster) maelstrom() {
	return c.maelstrom
}

func main() {
	bc := &BroadcastCluster{}
	bc.Run()
}

