			// Send topology_ok immediately
			c.RPC("topology_ok", nil, 0)

		case "broadcast":
			// This is a broadcast request from a client
			val, ok := msg.Message.(int)
			if !ok {
				log.Printf("Invalid message type for broadcast: %v", msg.Body)
				c.maelstrom.Reply("broadcast_err", map[string]int{"msg_id": int(val)}, 0)
				continue
