			vals := make([]int, 0, len(c.values))
			for v := range c.values {
				vals = append(vals, v)
			}
			sort.Ints(vals)

			// Reply with messages (which are just the values)
			c.maelstrom.Reply("read_ok", vals, 0)

		case "internal_message":
			// Process internal message from another node
			internalMsg := InternalMessage{}
			json.Unmarshal(msg.Body, &internalMsg)

			val := internalMsg.Value

			c.mu.Lock()
			c.values[val] = struct{}{}
			c.mu.Unlock()

			// Forward to all other nodes
			for _, dest := range c.nodeIDs {
				if msg.Src != dest {
					c.sendInternalMessage(val, dest)
				}
			}

			// Send internal message ack
			c.RPC("internal_msg_ack", nil, 0)

		default:
			log.Printf("Unhandled message type: %s", msg.Type)
			c.maelstrom.Reply("unknown_err", map[string]interface{}{"error": "unknown message type"}, 0)
		}
	}
}

