)

// Internal message type for cluster communication
type InternalMessage struct {
	Value int `json:"value"`
}

var clusterState sync.RWMutex
var values map[int]struct{} = make(map[int]struct{})

// Handle processes incoming messages of specific types
func (n *maelstrom.Node) Handle(msg string) {
	switch msg.Type {
	case "init":
		// Store node IDs from init message if available
		if n.ID != "" && n.NodeIDs != nil {
			values = make(map[int]struct{}) // reset values on new cluster
			for _, nodeID := range n.NodeIDs {
				log.Printf("Init: myID=%s, nodeCount=%d", nodeID, len(n.NodeIDs))
			}
		}

		// Send init_ok to acknowledge init
		n.Reply("init_ok", nil, 0)

	case "topology":
		// Store topology but we'll use all-to-all communication
		log.Printf("Topology received: %v", msg.Body)
		// Reply with topology_ok immediately
		n.Reply("topology_ok", nil, 0)

	case "broadcast":
		// Receive a value to broadcast to the cluster
		val := int(msg.Message.(int))
		values[val] = struct{}{}

		// Forward to all other nodes in the cluster (all-to-all)
		if n.NodeIDs != nil {
			for _, destID := range n.NodeIDs {
				if destID != msg.Src {
					internalMsg, _ := json.Marshal(InternalMessage{Value: val})
					n.RPC(destID, internalMsg)
				}
			}
		}

		// Reply to client with broadcast_ok
		n.Reply("broadcast_ok", nil, 0)

	case "read":
		// Return all values sorted
		vals := make([]int, 0, len(values))
		for v := range values {
			vals = append(vals, v)
		}
		sort.Ints(vals)

		// Send read_ok with the messages (which are just integers)
		n.Reply("read_ok", vals, 0)

	case "internal_message":
		// Process internal message from another node in the cluster
		internalMsg := InternalMessage{}
		json.Unmarshal(msg.Body, &internalMsg)

		val := internalMsg.Value

		// Add to our local values set
		values[val] = struct{}{}

		// Forward to all other nodes (all-to-all for reliability)
		if n.NodeIDs != nil {
			for _, destID := range n.NodeIDs {
				if destID != msg.Src {
					internalMsg2, _ := json.Marshal(InternalMessage{Value: val})
					n.RPC(destID, internalMsg2)
				}
			}
		}

		// Send ack back
		n.Reply("internal_msg_ack", nil, 0)

	default:
		log.Printf("Unhandled message type: %s", msg.Type)
		n.Reply("unknown_err", map[string]interface{}{"error": "unknown message type"}, 0)
	}
}

// Run starts the node processing
func (n *maelstrom.Node) Run() {
	log.Println("Running broadcast cluster node")
}

func main() {
	node := maelstrom.NewNode(func(n *maelstrom.Node) {
		n.Handle(marshalType("broadcast", 0))
		n.Handle(marshalType("read", 1))
		n.Handle(marshalType("internal_message", 2))
		n.Run()
	})

	// Start the node in a goroutine so it runs
	go node.Run()

	// Run forever since there's no specific exit condition for broadcast cluster
	select {}
}

